<?php
require_once dirname(__DIR__,3).'/bootstrap.php';$allowedRoles=[ROLE_NURSE];require APP_ROOT.'/app/middleware/RoleMiddleware.php';use App\Services\MedicalService;use PhpOffice\PhpSpreadsheet\IOFactory;
$errors=[];$success=0;if(isset($_GET['download_template'])){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="medical_record_import_template.csv"');$out=fopen('php://output','w');fputcsv($out,['StudentId','Diagnosis','Treatment','Notes','Severity']);fputcsv($out,['STUDENT_ID','Flu','Rest and fluids','Follow up','normal']);fclose($out);exit;}if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='import_records'&&!empty($_FILES['records_file'])){$file=$_FILES['records_file'];$extension=strtolower(pathinfo($file['name']??'',PATHINFO_EXTENSION));if($file['error']!==UPLOAD_ERR_OK||!in_array($extension,['csv','xlsx'],true)){$errors[]='Upload a valid CSV or XLSX file.';}else{try{$rows=IOFactory::load($file['tmp_name'])->getActiveSheet()->toArray(null,true,true,false);$header=array_map(fn($v)=>strtolower(preg_replace('/[^a-z0-9]/i','',(string)$v)),array_shift($rows)?:[]);$map=[];foreach($header as $i=>$name)$map[$name]=$i;foreach(array_slice($rows,0,1000) as $row){$value=fn($name,$fallback=-1)=>$row[$map[strtolower(preg_replace('/[^a-z0-9]/i','',$name))]??$fallback]??'';$student=sanitize($value('studentid',0));if($student==='')continue;$result=(new MedicalService())->create(['studentId'=>$student,'diagnosis'=>sanitize($value('diagnosis',1)),'treatment'=>sanitize($value('treatment',2)),'notes'=>sanitize($value('notes',3)),'severity'=>sanitize($value('severity',4)?:'normal'),'recordedBy'=>current_user()['uid']??current_user()['id']??null]);if(!empty($result['success']))$success++;}flash('success',"Imported {$success} medical record(s).");redirect(url('views/nurse/medical-records/bulk-import.php'));}catch(Throwable $e){$errors[]='Import failed: '.$e->getMessage();}}}$pageTitle='Bulk Medical Import';$navItems=[['icon'=>'bi-journal-medical','label'=>'Medical Records','href'=>url('views/nurse/medical-records/medical-records.php')],['icon'=>'bi-upload','label'=>'Import Records','href'=>url('views/nurse/medical-records/bulk-import.php'),'active'=>true]];require APP_ROOT.'/app/views/components/header.php';require APP_ROOT.'/app/views/components/sidebar.php';?>
<div class="main-content"><?php require APP_ROOT.'/app/views/components/navbar.php';?><?php require APP_ROOT.'/app/views/components/alerts.php';?><div class="content-wrapper"><div class="card stat-card p-4" style="max-width:760px"><h5 class="mb-3">Import Medical Records</h5><?php foreach($errors as $error):?><div class="alert alert-danger"><?=e($error)?></div><?php endforeach;?><form method="POST" enctype="multipart/form-data"><input type="hidden" name="action" value="import_records"><label class="form-label">CSV or XLSX file</label><input type="file" name="records_file" class="form-control mb-3" accept=".csv,.xlsx" required><p class="small text-muted">Headers: StudentId, Diagnosis, Treatment, Notes, Severity. Maximum 1,000 rows.</p><button class="btn btn-primary">Upload and import</button> <a class="btn btn-outline-secondary" href="<?=url('views/nurse/medical-records/bulk-import.php?download_template=1')?>">Download template</a></form></div></div></div><?php require APP_ROOT.'/app/views/components/footer.php';?>